"""Run next to worker-dispatch.py. Recover only a failed legacy mutation condenser.
No new assignment, worktree or git operations. Preserve history and record lineage.
"""
import fcntl,json,pathlib,runpy,sys,uuid,os

def main(lane: str):
 d=runpy.run_path(str(pathlib.Path(__file__).with_name('worker-dispatch.py')));api=d['api'];parent=d['M'];assert lane in ('transfer-buckets','workbook-month-range');pc=api('conversations/'+parent);root=pathlib.Path(pc['workspace']['working_dir']);reg=root/'.worker-registry';lock=(reg/'lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX);f=reg/(lane+'.json');rec=json.loads(f.read_text());old=rec['id'];c='conversations/'+old;j=api(c);tree=root/'worker-trees'/lane/'monori';assert tree.is_dir() and str(tree)==rec['worktree'];assert j['execution_status']=='error' and j['agent']['condenser']['llm']['model']=='openai/o-deepseek';ev=api(c+'/events/search?sort_order=TIMESTAMP_DESC&limit=6')['items'];assert any(e.get('code')=='NoCondensationAvailableException' and 'o-deepseek' in e.get('detail','') for e in ev)
 name='socrat-mutation-worker-qwen';ps=api('agent-profiles')['profiles'];
 if not any(p['name']==name for p in ps):api('agent-profiles/'+name,{'agent_kind':'openhands','llm_profile_ref':'qwen3.8-27b','tools':[{'name':'terminal'},{'name':'file_editor'}],'mcp_server_refs':[],'secret_refs':[],'integration_refs':[],'public_skills':[],'system_message_suffix':'One assigned worktree only. Use compact tool results. No merge. Keep an evidence checkpoint.','condenser':{'enabled':True,'max_size':32,'max_tokens':9000,'keep_first':1}})
 p=api('agent-profiles/'+name)['profile'];assert p['llm_profile_ref']=='qwen3.8-27b';cid=str(uuid.uuid5(uuid.NAMESPACE_URL,old+':recover-qwen'));new='conversations/'+cid;api('conversations',{'conversation_id':cid,'parent_conversation_id':parent,'workspace':pc['workspace'],'agent_profile_id':p['id'],'confirmation_policy':j['confirmation_policy'],'security_analyzer':j['security_analyzer'],'hook_config':j['hook_config'],'max_iterations':j['max_iterations'],'autotitle':False});check=api(new)['agent'];assert check['llm']['model']==check['condenser']['llm']['model']=='openai/qwen3.8-27b';assert api(c)['execution_status']=='error';rec['prior_ids']=rec.get('prior_ids',[])+[old];rec['id']=cid;t=f.with_suffix('.tmp');t.write_text(json.dumps(rec));os.replace(t,f);api(new,{'title':'Mutation #509 — '+lane+' (Qwen recovery)'},'PATCH');msg=f"Продолжай прежнее задание, не создавай новую ветку или worktree: {rec['task']}. Сначала cd {tree}, проверь состояние, PROGRESS.md рядом с worktree, имеющиеся тесты/результаты и дубли PR. Исходная история сохранена: {old}. Не перезапускай старый чат. Запиши краткое состояние перед длинными командами. Докажи mutant red, original green. Малый PR только через MONORI_PUBLISHER.md; не мержи. После PR проверь CI/reviews на текущем head.";print(lane,cid,api(new+'/events',{'role':'user','content':[{'type':'text','text':msg}],'run':True}))
if __name__=='__main__':main(sys.argv[1])
